using System.Text;

namespace NodaJs.Tools.Common;

/// <summary>
/// Writes generated TypeScript files into the repo. Every file starts with an auto-generated header.
/// Files are only rewritten when their content changes, and stale generated files in directories
/// the tool owns are deleted, so re-running a tool gives a minimal git diff.
/// </summary>
public sealed class GeneratedFiles
{
    private readonly string _tool;
    private readonly HashSet<string> _written = new(StringComparer.OrdinalIgnoreCase);
    private int _changed;

    public GeneratedFiles(string tool)
    {
        _tool = tool;
    }

    /// <summary>The auto-generated header comment, followed by an empty line.</summary>
    public static string Header(string tool, string command, IEnumerable<string>? extraLines = null)
    {
        var writer = new TypescriptWriter()
            .Comment("<auto-generated>")
            .Comment($"This file was generated by tools/{tool} ({command}) from {ToolEnvironment.Describe()}.")
            .Comment("Do not edit it by hand: re-run tools/generate.ps1 instead.");
        foreach (var line in extraLines ?? [])
            writer.Comment(line);
        return writer.Comment("</auto-generated>").WriteLine().ToString();
    }

    /// <summary>
    /// Writes a file relative to the repo root, with the auto-generated header for the given command.
    /// </summary>
    public void Write(string relativePath, string command, TypescriptWriter body, IEnumerable<string>? extraHeaderLines = null)
    {
        var content = Header(_tool, command, extraHeaderLines) + body;
        if (!content.EndsWith('\n')) content += "\n";
        var path = Path.GetFullPath(Path.Combine(ToolEnvironment.RepoRoot, relativePath));
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        _written.Add(path);
        if (File.Exists(path) && File.ReadAllText(path) == content)
            return;
        File.WriteAllText(path, content, new UTF8Encoding(encoderShouldEmitUTF8Identifier: false));
        _changed++;
        Console.WriteLine($"  wrote {relativePath.Replace('\\', '/')}");
    }

    /// <summary>
    /// Writes a binary file (e.g. a test fixture) relative to the repo root, as is: no header.
    /// </summary>
    public void WriteBinary(string relativePath, byte[] content)
    {
        var path = Path.GetFullPath(Path.Combine(ToolEnvironment.RepoRoot, relativePath));
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        _written.Add(path);
        if (File.Exists(path) && File.ReadAllBytes(path).AsSpan().SequenceEqual(content))
            return;
        File.WriteAllBytes(path, content);
        _changed++;
        Console.WriteLine($"  wrote {relativePath.Replace('\\', '/')}");
    }

    /// <summary>
    /// Deletes files matching <paramref name="searchPattern"/> (by default, *.generated.ts) under the given directory
    /// (relative to the repo root) which weren't written in this run.
    /// </summary>
    public void DeleteStale(string relativeDirectory, string searchPattern = "*.generated.ts")
    {
        var directory = Path.Combine(ToolEnvironment.RepoRoot, relativeDirectory);
        if (!Directory.Exists(directory))
            return;
        
        foreach (var file in Directory.EnumerateFiles(directory, searchPattern, SearchOption.AllDirectories))
        {
            if (_written.Contains(Path.GetFullPath(file)))
                continue;
            
            File.Delete(file);
            Console.WriteLine($"  deleted {Path.GetRelativePath(ToolEnvironment.RepoRoot, file).Replace('\\', '/')}");
            _changed++;
        }
    }

    public void Summarize() =>
        Console.WriteLine($"{_tool}: {_written.Count} files generated, {_changed} changed.");
}
